contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _value) public payable {
        uint beforeBal = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint afterBal = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            (reverted == (_value > beforeBal)) &&
            (reverted ? (afterBal == beforeBal) : (afterBal == beforeBal - _value)) &&
            (afterDeposits == beforeDeposits)
        );
    }

    receive() external payable {}
}

